import abc
import logging
import threading
import time

import six

from .config import loggers as ute_ue_logging
from .exceptions import VoiceCallNotStartedException, VoiceCallFinishException, VoiceCallInterrupted, \
    VoiceCallCantWaitForever, UeProcedureError
from .utils import param_checker

CALL_ITERRUPTED_CHECK_TIME = 1


@six.add_metaclass(abc.ABCMeta)
class VoiceCall:
    """Voice Call general object"""

    def __init__(self, name, ue_name, definition, logger_name='ute_ue'):
        """
        Construct new voice call

        :param name: name to assign for new voice call
        :param ue_name: name of UE where we start voice call at
        :param definition: description of voice call, instance of VoiceCallDefinition
        :param logger_name: where to put logs from this voice call
        """
        raw_logger = logging.getLogger(logger_name)
        self.logger = ute_ue_logging.LoggerAdapter4EmptyExtra(raw_logger, {'area': 'VOICE_CALL'})
        self.name = name
        self.hosting_ue_name = ue_name
        self.definition = definition

    def __str__(self):
        vc_info = f"{self.__class__.__name__} '{self._fullname()}' to {self.get_call_to_number()}"
        return vc_info

    def _fullname(self):
        fname = f"{self.hosting_ue_name}.{self.name}"
        return fname

    @abc.abstractmethod
    def start_voice_call(self):
        """Starts voice call."""
        pass

    @abc.abstractmethod
    def stop_voice_call(self):
        """
        Stops voice call.

        :raises: :py:class:`ute_ue.exceptions.VoiceCallInterrupted`: when voice call is interrupted in the middle of calling
        :raises: :py:class:`ute_ue.exceptions.VoiceCallNotStartedException`: if voice call haven't started
        :raises: :py:class:`ute_ue.exceptions.VoiceCallFinishException`: if self.dont_raise_when_stop_finished_voice_call
        and this voice call is already finished
        :return: None
        """
        pass

    @abc.abstractmethod
    def await_voice_call_finish(self):
        """
        Awaits until voice calls finish, based on duration time of voice call.

        :raises: :py:class:`ute_ue.exceptions.VoiceCallInterrupted`: when voice call is interrupted in the middle of calling
        :raises: :py:class:`ute_ue.exceptions.VoiceCallCantWaitForever`: if duration time is forever
        :raises: :py:class:`ute_ue.exceptions.VoiceCallNotStartedException`: if voice call haven't started
        :raises: :py:class:`ute_ue.exceptions.VoiceCallFinishException`: if self.dont_raise_when_stop_finished_voice_call
        and this voice call is already finished
        :return: None
        """
        pass

    @abc.abstractmethod
    def is_finished(self):
        """Returns if Voice Call have finished."""
        pass

    @abc.abstractmethod
    def merge_into_conference(self, other_call):
        """Merge with other_call into conference."""
        pass

    @abc.abstractmethod
    def hold(self):
        """Holds ongoing voice call"""
        pass

    @abc.abstractmethod
    def retrieve(self):
        """Retrieves holded voice call"""
        pass

    @abc.abstractmethod
    def drop(self):
        """Drops incoming voice call"""
        pass

    @abc.abstractmethod
    def answer(self, with_video=False):
        """Answers incoming voice call"""
        pass

    @abc.abstractmethod
    def upgrade(self):
        """Upgrades to video call"""
        pass

    @abc.abstractmethod
    def downgrade(self):
        """Downgrades to voice call"""
        pass

    @abc.abstractmethod
    def send_dtmf(self, tones, tone_duration):
        """Sends DTMF tones through voice channel."""
        pass

    @abc.abstractmethod
    def get_state(self):
        """Returns voice_call actual state."""
        pass

    def start(self):
        """Starts voice call - short python API alias."""
        self.start_voice_call()

    def stop(self):
        """Stop voice call - short python API alias.

        :raises: :py:class:`ute_ue.exceptions.VoiceCallInterrupted`: when voice call is interrupted in the middle of calling
        :raises: :py:class:`ute_ue.exceptions.VoiceCallNotStartedException`: if voice call haven't started
        :raises: :py:class:`ute_ue.exceptions.VoiceCallFinishException`: if self.dont_raise_when_stop_finished_voice_call
        and this voice call is already finished
        :return: None
        """
        self.stop_voice_call()

    def await_finish(self):
        """
        Awaits until voice calls finish, based on duration time of voice call - short python API alias.

        :raises: :py:class:`ute_ue.exceptions.VoiceCallInterrupted`: when voice call is interrupted in the middle of calling
        :raises: :py:class:`ute_ue.exceptions.VoiceCallCantWaitForever`: if duration time is forever
        :raises: :py:class:`ute_ue.exceptions.VoiceCallNotStartedException`: if voice call haven't started
        :raises: :py:class:`ute_ue.exceptions.VoiceCallFinishException`: if self.dont_raise_when_stop_finished_voice_call
        and this voice call is already finished
        :return: None
        """
        self.await_voice_call_finish()


class VoiceCallDefinition:
    """Defination of voice call"""

    def __init__(self, to, duration='forever', timeout_start_call=60, timeout_end_call=60, dialing_timeout=None,
                 allow_parallel_calls=False, with_video=False):
        """

        :param to:
        :param duration:
        :param timeout_start_call:
        :param timeout_end_call:
        :param dialing_timeout:
        :param allow_parallel_calls:
        :param with_video:
        """
        errors = []

        self.to = to
        self.duration, self.forever_duration = self._validate_and_return_duration(duration, errors)
        self.timeout_start_call = self._validate_and_return_timeout(timeout_start_call, errors)
        if dialing_timeout is None:
            dialing_timeout = -1
        self.dialing_timeout = self._validate_and_return_timeout(dialing_timeout, errors)
        self.timeout_end_call = self._validate_and_return_timeout(timeout_end_call, errors)
        self.allow_parallel_calls = allow_parallel_calls
        self.with_video = with_video

        if errors:
            raise ValueError("List of errors:\n  -{}".format('\n -'.join(errors)))

    def _validate_and_return_duration(self, duration, errors):
        try:
            if isinstance(duration, six.string_types):
                converted_duration = param_checker.convert_timestring(duration)
                forever = False
                if duration == 'forever':
                    forever = True
                return converted_duration, forever
            else:
                return float(duration), False
        except ValueError as exp:
            errors.append(str(exp))
            return None, False

    def _validate_and_return_timeout(self, timeout, errors):
        try:
            if isinstance(timeout, six.string_types):
                converted_timeout = param_checker.convert_timestring(timeout)
                return converted_timeout
            else:
                return float(timeout)
        except ValueError as exp:
            errors.append(str(exp))
            return 60.0


class DefaultBaseVoiceCall(VoiceCall):
    """Common part for many impls of VoiceCall."""

    def __init__(self, name, ue_name, definition, logger_name='ute_ue'):
        """
        Construct new DefaultBaseVoiceCall

        :param name: name to assign for new voice call
        :param ue_name: name of UE where we start voice call at
        :param definition: description of voice call, instance of VoiceCallDefinition
        :param logger_name: where to put logs from this voice call
        """
        super().__init__(name, ue_name, definition, logger_name)
        self.call_not_finish = True
        self._process_end_call_timer = None
        self._called_await_or_stop = False
        self._called_await_or_stop_lock = threading.RLock()
        self.call_start_time = None
        self.dont_raise_when_stop_finished_voice_call = True
        self.finished_calls_times = []

    def _register_finished_call_time(self, t):
        self.logger.debug(f"_register_finished_call_time t = {t}")
        self.finished_calls_times.append(t)

    def start_voice_call(self):
        """Starts voice call."""
        number = self.get_call_to_number()
        self.logger.debug(f"start_voice_call to {number}")
        self._start_call_on_ue(number)
        self.call_start_time = time.time()
        self.logger.debug(f"start_voice_call, call_start_time = {self.call_start_time}")
        if not self.definition.forever_duration:
            duration = self.definition.duration
            self.logger.debug(f"start_voice_call, not forever duration, so run timer with duration = {duration}")
            self._process_end_call_timer = self._schedule_process_end_call(duration)
            self._process_end_call_timer.start()

    def get_call_to_number(self):
        """
        Get calling number to which this Voice Call would call.
        :return: string like "+48123456789"
        """
        return self.definition.to

    def _schedule_process_end_call(self, duration):
        return threading.Timer(duration, self._process_end_call)

    def await_voice_call_finish(self):
        """
        Awaits until voice calls finish, based on duration time of vaoice call.

        :raises: :py:class:`ute_ue.exceptions.VoiceCallInterrupted`: when voice call is insterrupted in the middle of calling
        :raises: :py:class:`ute_ue.exceptions.VoiceCallCantWaitForever`: if duration time is forever
        :raises: :py:class:`ute_ue.exceptions.VoiceCallNotStartedException`: if voice call haven't started
        :raises: :py:class:`ute_ue.exceptions.VoiceCallFinishException`: if self.dont_raise_when_stop_finished_voice_call
        and this voice call is already finished
        :return: None
        """
        self.logger.info("await_voice_call_finish")
        self._raise_if_need_forever_duration()
        self._raise_if_need_not_started('await')
        err_msg = f"{self} is finished, can't await again"
        if not self._mark_true_called_await_or_stop(err_msg):
            return
        if self.call_not_finish:
            self.logger.debug("await_voice_call_finish: call is not finish, so I gonna wait")
            expect_end_time = self.call_start_time + self.definition.duration
            while time.time() <= expect_end_time:
                self.logger.debug("await_voice_call_finish: _check_voice_call_interrupted()")
                self._check_voice_call_interrupted()
                sleep_time = min(CALL_ITERRUPTED_CHECK_TIME, abs(expect_end_time - time.time()))
                self.logger.debug(f"await_voice_call_finish: sleep for {sleep_time}")
                time.sleep(sleep_time)
            self.logger.debug("await_voice_call_finish: _register_finished_call_time()")
            self._register_finished_call_time(time.time() - self.call_start_time)
            self.logger.debug("await_voice_call_finish: _end_call_on_ue()")
            self._end_call_on_ue()
            self.call_not_finish = False
        else:
            self.logger.debug("await_voice_call_finish: call is finish, nothing to do")
        self.logger.debug("await_voice_call_finish: end")

    def _raise_if_need_not_started(self, action):
        if self.call_start_time is None:
            err_msg = f"Please start {self} before {action} on it."
            raise VoiceCallNotStartedException(err_msg)

    def _raise_if_need_forever_duration(self):
        if self.definition.forever_duration:
            raise VoiceCallCantWaitForever()

    def _mark_true_called_await_or_stop(self, err_msg):
        self.logger.debug(f"_mark_true_called_await_or_stop, err_msg = {err_msg}")
        with self._called_await_or_stop_lock:
            if self._called_await_or_stop:
                self.logger.debug("_mark_true_called_await_or_stop, already _called_await_or_stop = True")
                if self.dont_raise_when_stop_finished_voice_call:
                    return False
                raise VoiceCallFinishException(err_msg)
            self._called_await_or_stop = True
        return True

    def is_finished(self):
        """
        Returns if Voice Call have finished.
        :return: bool
        """
        return not self.call_not_finish

    def stop_voice_call(self):
        """
        Stops voice call.

        :raises: :py:class:`ute_ue.exceptions.VoiceCallInterrupted`: when voice call is insterrupted in the middle of calling
        :raises: :py:class:`ute_ue.exceptions.VoiceCallNotStartedException`: if voice call haven't started
        :raises: :py:class:`ute_ue.exceptions.VoiceCallFinishException`: if self.dont_raise_when_stop_finished_voice_call
        and this voice call is already finished
        :return: None
        """
        # if not self.definition.forever_duration:
        #     self.logger.warning("Stop voice call of non-forever {}".format(self))
        self.logger.info("stop_voice_call")
        self._raise_if_need_not_started('stop')
        err_msg = f"{self} is finished, can't stop again"
        if not self._mark_true_called_await_or_stop(err_msg):
            return
        self._check_voice_call_interrupted()
        if not self.call_not_finish:
            return
        self._register_finished_call_time(time.time() - self.call_start_time)
        with self._called_await_or_stop_lock:
            if self._process_end_call_timer:
                self._process_end_call_timer.cancel()
                self.logger.debug("stop_voice_call: _process_end_call_timer terminated")
        self._end_call_on_ue()
        self.call_not_finish = False

    @abc.abstractmethod
    def _start_call_on_ue(self, to):
        pass

    @abc.abstractmethod
    def _end_call_on_ue(self):
        pass

    def _check_voice_call_interrupted(self):
        self.logger.debug("_check_voice_call_interrupted()")
        if self._is_iterrupted():
            self.logger.info("Voice call has been iterrupted")
            if self.call_not_finish:
                self._register_finished_call_time(time.time() - self.call_start_time)
                self._end_call_on_ue()
            raise VoiceCallInterrupted()
        else:
            self.logger.debug("_check_voice_call_interrupted: voice call not interrupted")

    def _is_iterrupted(self):
        return False

    def _process_end_call(self):
        self.logger.debug("_process_end_call() starting")
        with self._called_await_or_stop_lock:
            if self._process_end_call_timer:
                self._process_end_call_timer.cancel()
            if self._called_await_or_stop:
                self.logger.debug("_process_end_call _called_await_or_stop = True")
                return
        self._register_finished_call_time(time.time() - self.call_start_time)
        self._end_call_on_ue()
        self.call_not_finish = False

    def merge_into_conference(self, other_call):
        """
        Merges current call with other_call into conference.
        :param other_call:
        :return:
        """
        if other_call.name == self.name:
            raise UeProcedureError(f"Cannot merge single call '{self._fullname()}' into conference!")
        if other_call.hosting_ue_name != self.hosting_ue_name:
            calls_info = f"{self._fullname()} + {other_call._fullname()}"
            err_msg = f"Merging calls into conference failed - calls from different UEs: {calls_info}"
            raise UeProcedureError(err_msg)
        self._merge_into_conference(other_call=other_call)

    def _merge_into_conference(self, other_call):
        raise NotImplementedError(f"Conference feature is not implemented for calls of class: '{self.__class__.__name__}'")

    def hold(self):
        """
        Holds ongoing voice call
        :return:
        """
        raise NotImplementedError

    def retrieve(self):
        """
        Retrieves holded voice call
        :return:
        """
        raise NotImplementedError

    def answer(self, with_video=False):
        """
        Answers incoming voice call
        :return:
        """
        raise NotImplementedError

    def drop(self):
        """
        Drops incoming voice call
        :return:
        """
        self._end_call_on_ue()

    def upgrade(self):
        """
        Upgrades to video call
        :return:
        """
        raise NotImplementedError

    def downgrade(self):
        """
        Downgrades to voice call
        :return:
        """
        raise NotImplementedError

    def send_dtmf(self, tones, tone_duration):
        """
        Sends DTMF tones through voice channel.
        :param tones:
        :param tone_duration:
        :return:
        """
        dtmf_allowed_characters = [str(num) for num in range(10)]
        dtmf_allowed_characters.extend("*#ABCD")

        for tone in tones:
            if tone not in dtmf_allowed_characters:
                raise AttributeError("{}: '{}' {}: {}".format('Provided not DTMF supported character', tone,
                                                              'DTMF supports tones for characters',
                                                              dtmf_allowed_characters))

        try:
            tone_duration = int(tone_duration)
        except ValueError:
            raise AttributeError("Tone duration must be integer!")

        self._send_dtmf(tones, tone_duration)

    def _send_dtmf(self, tones, tone_duration):
        raise NotImplementedError()

    def get_state(self):
        raise NotImplementedError()
